 if($op==='delete'){$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);if(in_array($type,['articles','products','classes','clubs'],true)){db()->prepare("DELETE FROM {$type} WHERE id=?")->execute([$id]);flash('Item removed.');}go('control-room/'.$tab);}
 if(in_array($op,['save-article','save-product','save-class','save-club'],true)){
