   elseif($op==='save-product'){$fields=['name'=>trim((string)$_POST['name']),'slug'=>trim((string)$_POST['slug']),'category'=>trim((string)$_POST['category']),'description'=>trim((string)$_POST['description']),'price'=>(float)$_POST['price'],'image_url'=>trim((string)$_POST['image_url']),'badge'=>trim((string)$_POST['badge']),'active'=>$active];$table='products';$cols=array_keys($fields);}
   elseif($op==='save-class'){$fields=['name'=>trim((string)$_POST['name']),'slug'=>trim((string)$_POST['slug']),'category'=>trim((string)$_POST['category']),'description'=>trim((string)$_POST['description']),'duration'=>trim((string)$_POST['duration']),'level'=>trim((string)$_POST['level']),'image_url'=>trim((string)$_POST['image_url']),'active'=>$active];$table='classes';$cols=array_keys($fields);}
   else{$fields=['name'=>trim((string)$_POST['name']),'slug'=>trim((string)$_POST['slug']),'address'=>trim((string)$_POST['address']),'description'=>trim((string)$_POST['description']),'image_url'=>trim((string)$_POST['image_url']),'hours'=>trim((string)$_POST['hours']),'membership'=>trim((string)$_POST['membership']),'active'=>$active];$table='clubs';$cols=array_keys($fields);}
   if($id){$sql="UPDATE {$table} SET ".implode(',',array_map(fn($col)=>"{$col}=?",$cols)).' WHERE id=?';db()->prepare($sql)->execute([...array_values($fields),$id]);}else{$sql="INSERT INTO {$table} (".implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')';db()->prepare($sql)->execute(array_values($fields));}flash('Changes saved.');
  }catch(Throwable $exception){flash('Could not save. Check that every required field is filled and the slug is unique.','error');}
  go('control-room/'.match($op){'save-article'=>'articles','save-product'=>'products','save-class'=>'classes',default=>'clubs'});
 }
}
$counts=['articles'=>(int)db()->query('SELECT COUNT(*) FROM articles')->fetchColumn(),'products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),'classes'=>(int)db()->query('SELECT COUNT(*) FROM classes')->fetchColumn(),'clubs'=>(int)db()->query('SELECT COUNT(*) FROM clubs')->fetchColumn(),'leads'=>(int)db()->query("SELECT COUNT(*) FROM leads WHERE status='New'")->fetchColumn()];
