lue="<?=e($obj['author']??'Fitzeno Team')?>"></label><?php elseif($productMode):?><label>Price (LKR)<input name="price" type="number" min="0" step="0.01" required value="<?=e((string)($obj['price']??''))?>"></label><label>Badge<input name="badge" value="<?=e($obj['badge']??'')?>"></label><label class="wide">Description<textarea name="description" required rows="4"><?=e($obj['description']??'')?></textarea></label><?php elseif(!$clubMode):?><label>Duration<input name="duration" value="<?=e($obj['duration']??'45 min')?>"></label><label>Level<input name="level" value="<?=e($obj['level']??'All levels')?>"></label><label class="wide">Description<textarea name="description" required rows="4"><?=e($obj['description']??'')?></textarea></label><?php endif;?><label class="wide">Image URL<input name="image_url" value="<?=e($obj['image_url']??'')?>"></label><label class="check-label"><input type="checkbox" name="active" <?=!isset($obj['active'])||$obj['active']?'checked':''?>> <?=($tab==='articles'?'Published':'Visible on the site')?></label></div><div class="editor-actions"><button class="button button-dark">SAVE CHANGES ↗</button><a class="back-link" href="<?=e(url('control-room/'.$tab))?>">Cancel</a></div></form><?php endif;?><div class="admin-list"><div class="list-heading"><span>NAME</span><span>CATEGORY</span><span>STATUS / PRICE</span><span>ACTIONS</span></div><?php foreach($rows as $row):?><article class="list-row"><div><strong><?=e($row['title']??$row['name'])?></strong><small>/<?=e(match($tab){'articles'=>'journal/','products'=>'shop/','clubs'=>'clubs/',default=>'classes/'})?><?=e($row['slug'])?></small></div><span><?=e($row['category'])?></span><span><?php if($tab==='products'):?>LKR <?=number_format((float)$row['price'])?><?php else:?><?=!empty($row['published'])||!empty($row['active'])?'Live':'Draft'?><?php endif;?></span><div class="row-actions"><a href="?edit=<?=$row['id']?>">Edit</a><form method="post" onsubmit="return confirm('Remove this item?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="op" value="delete"><input type="hidden" name="type" value="<?=e($tab)?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button>Delete</button></form></div></article><?php endforeach;?></div><?php endif;?></main></body></html>
